<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ArrowRight, BookOpen, CalendarDays, Clock3 } from '@lucide/vue'
import type { LearnOutcomeDraft, LearnOutcomeIntent } from '~/types/learn-v2-journey'
const { draft } = defineProps<{ draft: LearnOutcomeDraft }>()
const emit = defineEmits<{ saveDraft: [intent: LearnOutcomeIntent]; continueToSources: [intent: LearnOutcomeIntent] }>()
const form = ref<LearnOutcomeDraft>({ ...draft })
watch(() => draft, value => { form.value = { ...value } }, { deep: true })
const valid = computed(() => form.value.outcome.trim().length >= 8)
function intent(): LearnOutcomeIntent { return { ...form.value, outcome: form.value.outcome.trim() } }
</script>
<template>
  <section class="mx-auto max-w-5xl px-4 py-8 sm:px-6" data-testid="learn-v2-outcome-canvas"><header><p class="font-inter text-xs font-medium uppercase tracking-[0.16em] text-primary">Start with an outcome</p><h1 class="mt-2 font-dm-sans text-3xl font-bold tracking-tight">What do you want to be able to do?</h1><p class="mt-2 max-w-2xl text-sm text-muted-foreground">A learning plan is a durable workspace, not a generated document. You will review the evidence and map before anything is scheduled.</p></header><div class="mt-7 grid gap-6 lg:grid-cols-[minmax(0,1fr)_18rem]"><div class="space-y-6"><UiCard class="gap-4 p-5"><label for="learn-v2-outcome" class="font-dm-sans text-base font-semibold">Your outcome</label><textarea id="learn-v2-outcome" v-model="form.outcome" data-testid="learn-v2-outcome-input" rows="4" class="w-full resize-y rounded-lg border border-input bg-background px-3 py-3 text-sm leading-6 placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" placeholder="For example: Explain cancellation and error boundaries in async JavaScript to a teammate." /><p class="text-xs text-muted-foreground">Describe an understanding or capability, rather than a course title.</p></UiCard><UiCard class="gap-4 p-5"><fieldset><legend class="font-dm-sans text-base font-semibold">How will you use it?</legend><div class="mt-3 grid gap-2 sm:grid-cols-3"><label v-for="option in [{ id: 'understand', label: 'Understand' }, { id: 'prepare', label: 'Prepare' }, { id: 'apply', label: 'Apply' }]" :key="option.id" class="cursor-pointer rounded-lg border border-border px-3 py-3 text-sm transition-colors has-[:checked]:border-primary has-[:checked]:bg-primary/10"><input v-model="form.mode" class="sr-only" type="radio" name="learn-mode" :value="option.id"><span class="font-medium">{{ option.label }}</span></label></div></fieldset><div class="grid gap-4 sm:grid-cols-2"><label class="text-sm font-medium">Depth<select v-model="form.depth" class="mt-1.5 w-full rounded-lg border border-input bg-background px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><option value="overview">Overview</option><option value="working">Working knowledge</option><option value="deep">Deep practice</option></select></label><label class="text-sm font-medium">Source policy<select v-model="form.sourcePolicy" class="mt-1.5 w-full rounded-lg border border-input bg-background px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><option value="folder_only">Folder only</option><option value="folder_plus_web">Folder + web</option><option value="web_only">Web only</option></select></label></div></UiCard></div><aside class="space-y-4"><UiCard class="gap-3 p-4"><div class="flex items-center gap-2 text-sm font-medium"><BookOpen class="h-4 w-4 text-primary" />Learning context</div><p class="text-sm">{{ form.folderName ?? 'Choose a folder when connected' }}</p><p class="text-xs text-muted-foreground">{{ form.folderDocumentCount }} folder document{{ form.folderDocumentCount === 1 ? '' : 's' }} available for evidence review.</p></UiCard><UiCard class="gap-3 p-4"><div class="flex items-center gap-2 text-sm font-medium"><Clock3 class="h-4 w-4 text-primary" />Study rhythm</div><label class="text-sm">Session length<select v-model.number="form.sessionMinutes" class="mt-1.5 w-full rounded-lg border border-input bg-background px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><option v-for="minutes in [15, 20, 25, 30, 45, 60]" :key="minutes" :value="minutes">{{ minutes }} minutes</option></select></label><label class="text-sm">Target date <input v-model="form.targetDate" type="date" class="mt-1.5 w-full rounded-lg border border-input bg-background px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"></label><p class="flex gap-2 text-xs text-muted-foreground"><CalendarDays class="h-4 w-4 shrink-0" />You will choose availability and review the feasibility before accepting a plan.</p></UiCard></aside></div><footer class="sticky bottom-0 mt-8 flex flex-wrap justify-end gap-3 border-t border-border bg-background/90 py-4 backdrop-blur"><UiButton variant="ghost" @click="emit('saveDraft', intent())">Save draft</UiButton><UiButton :disabled="!valid" data-testid="learn-v2-outcome-continue" @click="emit('continueToSources', intent())">Continue to sources <ArrowRight class="ml-1 h-4 w-4" /></UiButton></footer></section>
</template>
